//! Docutils XML: the document tree as XML, as docutils' XML writer
//! (`docutils --writer=xml`, `docutils.writers.docutils_xml`) writes it,
//! following the [Docutils Generic DTD].
//!
//! ```
//! use lsdocs_rst::{Parser, XmlOptions};
//!
//! let doc = Parser::new().source("example").parse("Hello, *world*.\n");
//! let options = XmlOptions { xml_declaration: false, doctype_declaration: false, ..XmlOptions::default() };
//! assert_eq!(
//!     doc.to_xml(&options),
//!     "<!-- Generated by lsdocs-rst -->\n\
//!      <document source=\"example\"><paragraph>Hello, <emphasis>world</emphasis>.</paragraph></document>"
//! );
//! ```
//!
//! The one difference from docutils is the generator comment, which names
//! this crate. Raw XML (a `raw` element with the `xml` format) is written
//! as it is, without the check docutils makes that it is well-formed.
//!
//! [Docutils Generic DTD]: https://docutils.sourceforge.io/docs/ref/docutils.dtd

use crate::nodes::{Element, Kind, Node, Text};

/// How to write XML; the defaults are docutils'.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[cfg_attr(
    feature = "serde",
    derive(serde::Serialize, serde::Deserialize),
    serde(default, deny_unknown_fields)
)]
pub struct XmlOptions {
    /// Line breaks before and after tags (docutils' `newlines`).
    pub newlines: bool,
    /// Line breaks and four-space indentation (docutils' `indents`).
    pub indents: bool,
    /// Start with `<?xml version="1.0" encoding="utf-8"?>`.
    pub xml_declaration: bool,
    /// Then the `DOCTYPE` of the Docutils Generic DTD.
    pub doctype_declaration: bool,
}

impl Default for XmlOptions {
    fn default() -> Self {
        Self {
            newlines: false,
            indents: false,
            xml_declaration: true,
            doctype_declaration: true,
        }
    }
}

const DOCTYPE: &str = "<!DOCTYPE document PUBLIC \
    \"+//IDN docutils.sourceforge.net//DTD Docutils Generic//EN//XML\" \
    \"http://docutils.sourceforge.net/docs/ref/docutils.dtd\">\n";

/// The comment after the declarations.
pub(crate) const GENERATOR: &str = "<!-- Generated by lsdocs-rst -->\n";

impl Element {
    /// The element (usually a whole document) as Docutils XML.
    pub fn to_xml(&self, options: &XmlOptions) -> String {
        let mut writer = Writer {
            out: String::new(),
            newline: if options.newlines || options.indents {
                "\n"
            } else {
                ""
            },
            indent: if options.indents { "    " } else { "" },
            level: 0,
            in_simple: 0,
            fixed_text: 0,
        };
        if options.xml_declaration {
            writer
                .out
                .push_str("<?xml version=\"1.0\" encoding=\"utf-8\"?>\n");
        }
        if options.doctype_declaration {
            writer.out.push_str(DOCTYPE);
        }
        writer.out.push_str(GENERATOR);
        writer.element(self);
        writer.out
    }
}

/// docutils' `XMLTranslator`.
struct Writer {
    out: String,
    newline: &'static str,
    indent: &'static str,
    /// Indentation level.
    level: usize,
    /// Nesting inside mixed-content elements, where nothing is indented.
    in_simple: usize,
    /// Nesting inside elements whose text keeps its line breaks.
    fixed_text: usize,
}

impl Writer {
    fn element(&mut self, e: &Element) {
        let class = Class::of(&e.kind);
        if self.in_simple == 0 {
            self.out.push_str(&self.indent.repeat(self.level));
        }
        self.out.push_str(&e.starttag_with(quoteattr));
        if !class.inline {
            self.level += 1;
        }
        if class.fixed {
            self.fixed_text += 1;
        }
        if class.simple {
            self.in_simple += 1;
        }
        if self.in_simple == 0 {
            self.out.push_str(self.newline);
        }
        let raw_xml = e.kind == Kind::Raw
            && e.attributes
                .get_str("format")
                .is_some_and(|f| f.split_whitespace().any(|f| f == "xml"));
        if raw_xml {
            self.out.push_str(&e.astext());
        } else {
            for child in &e.children {
                match child {
                    Node::Element(c) => self.element(c),
                    Node::Text(t) => self.text(t),
                }
            }
        }
        if !class.inline {
            self.level = self.level.saturating_sub(1);
        }
        if self.in_simple == 0 {
            self.out.push_str(&self.indent.repeat(self.level));
        }
        self.out.push_str(&format!("</{}>", e.kind.tag()));
        if class.fixed {
            self.fixed_text -= 1;
        }
        if class.simple {
            self.in_simple -= 1;
        }
        if self.in_simple == 0 {
            self.out.push_str(self.newline);
        }
    }

    fn text(&mut self, t: &Text) {
        let text = escape(&t.value);
        if self.fixed_text == 0 {
            let indented = format!("\n{}", self.indent.repeat(self.level));
            self.out.push_str(&text.replace('\n', &indented));
        } else {
            self.out.push_str(&text);
        }
    }
}

/// What the writer needs to know of a node class.
struct Class {
    /// `nodes.Inline`: not indented.
    inline: bool,
    /// `nodes.FixedTextElement` or `nodes.literal`: text keeps its line
    /// breaks.
    fixed: bool,
    /// `nodes.TextElement`, `meta`, `image`, `colspec`, `transition`: mixed
    /// content, written on one line.
    simple: bool,
}

impl Class {
    fn of(kind: &Kind) -> Class {
        let tag = kind.tag();
        let inline = INLINE.contains(&tag);
        let text_element = (inline && tag != "image") || TEXT_ELEMENTS.contains(&tag);
        Class {
            inline,
            fixed: FIXED.contains(&tag),
            simple: text_element || matches!(tag, "meta" | "image" | "colspec" | "transition"),
        }
    }
}

/// `nodes.Inline` subclasses.
const INLINE: &[&str] = &[
    "target",
    "raw",
    "emphasis",
    "strong",
    "literal",
    "reference",
    "footnote_reference",
    "citation_reference",
    "substitution_reference",
    "title_reference",
    "abbreviation",
    "acronym",
    "superscript",
    "subscript",
    "math",
    "image",
    "inline",
    "problematic",
    "generated",
];

/// `nodes.TextElement` subclasses that are not inline (the inline ones,
/// but `image`, are text elements too).
const TEXT_ELEMENTS: &[&str] = &[
    "title",
    "subtitle",
    "author",
    "organization",
    "address",
    "contact",
    "version",
    "revision",
    "status",
    "date",
    "copyright",
    "paragraph",
    "term",
    "classifier",
    "field_name",
    "option_string",
    "option_argument",
    "literal_block",
    "doctest_block",
    "math_block",
    "line",
    "attribution",
    "comment",
    "substitution_definition",
    "label",
    "caption",
    "rubric",
];

/// `nodes.FixedTextElement` subclasses and `nodes.literal`.
const FIXED: &[&str] = &[
    "address",
    "literal_block",
    "doctest_block",
    "math_block",
    "comment",
    "raw",
    "literal",
];

/// `xml.sax.saxutils.escape`.
fn escape(text: &str) -> String {
    text.replace('&', "&amp;")
        .replace('>', "&gt;")
        .replace('<', "&lt;")
}

/// `xml.sax.saxutils.quoteattr`: escaped, line breaks and tabs as
/// character references, in double quotes unless the value has double
/// quotes and no single ones.
fn quoteattr(value: &str) -> String {
    let value = escape(value)
        .replace('\n', "&#10;")
        .replace('\r', "&#13;")
        .replace('\t', "&#9;");
    if value.contains('"') {
        if value.contains('\'') {
            format!("\"{}\"", value.replace('"', "&quot;"))
        } else {
            format!("'{value}'")
        }
    } else {
        format!("\"{value}\"")
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn quoting_matches_python() {
        assert_eq!(quoteattr("a<b>&c"), "\"a&lt;b&gt;&amp;c\"");
        assert_eq!(quoteattr("say \"hi\""), "'say \"hi\"'");
        assert_eq!(quoteattr("it's \"x\""), "\"it's &quot;x&quot;\"");
        assert_eq!(quoteattr("a\nb\tc"), "\"a&#10;b&#9;c\"");
    }
}
